// Hand-written `@nestjs/bull` stub for the flowatlas fixture suite.
//
// It is here for one row of §10: `@Processor('mail')` + `@Process('send-email')`
// is the bull-era consumer shape, and `@Process` exists only in this package —
// `@nestjs/bullmq` has never exported it. A repo mid-migration carries both,
// and both are detection keys for the single `bullmq` adapter (§7), so having
// the two styles side by side changes which adapter runs not at all.
//
// `Job` is deliberately absent. It comes from `bull`, which this package takes
// as a peer, and it used to be folded in here so the fixture would ship one
// stub fewer. That saved a file by having the fixture import a name the real
// package does not export, which is the one thing a stub may not do.

export declare function Processor(queueName?: string): ClassDecorator;
export declare function Process(name?: string): MethodDecorator;
export declare function InjectQueue(name?: string): ParameterDecorator;
export declare function OnQueueFailed(): MethodDecorator;
